What does this print?

```typescript
interface Counter {
  (): number;
  count: number;
}
function makeCounter(step: number): Counter {
  const counter = (() => (counter.count += step)) as Counter;
  counter.count = 0;
  return counter;
}
const byTwo = makeCounter(2);
const byFive = makeCounter(5);
byTwo();
byFive();
console.log(byTwo(), byFive.count, byTwo.count);
export {};
```
